# ruff: noqa: E501
from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["work"])

_WORK_BOARD_HTML = """<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>SmartCore 事项看板</title>
<style>
:root{--bg:#f5f7fb;--surface:#fff;--surface2:#f8fafc;--border:#e2e8f0;--text:#111827;--muted:#64748b;--accent:#2563eb;--accent-soft:#eaf2ff;--green:#16a34a;--orange:#f59e0b;--red:#ef4444;--purple:#7c3aed;--shadow:0 8px 24px rgba(15,23,42,.05)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Segoe UI,system-ui,-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}a{text-decoration:none;color:inherit}button,input{font:inherit}.layout{display:grid;grid-template-columns:236px minmax(0,1fr);min-height:100vh}.sidebar{background:var(--surface);border-right:1px solid var(--border);padding:22px 18px;position:sticky;top:0;height:100vh}.brand{display:flex;gap:10px;align-items:center;margin-bottom:34px}.brand-mark{width:36px;height:36px;border-radius:10px;background:var(--accent);color:#fff;display:grid;place-items:center;font-weight:800}.brand-title{font-size:18px;font-weight:750}.brand-sub{font-size:12px;color:var(--muted)}.nav{display:grid;gap:8px}.nav-link{display:flex;gap:10px;align-items:center;min-height:42px;padding:0 12px;border-radius:12px;color:#475569;font-weight:620;font-size:14px}.nav-link:hover{background:var(--surface2)}.nav-link.active{background:var(--accent-soft);color:var(--accent)}.nav-ico{width:20px;text-align:center}.main{min-width:0}.topbar{height:76px;background:rgba(255,255,255,.92);border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 28px;position:sticky;top:0;z-index:10;backdrop-filter:blur(12px)}.search{width:min(520px,48vw);height:40px;border:1px solid #cbd5e1;border-radius:12px;background:#fff;display:flex;align-items:center;gap:10px;padding:0 12px;color:var(--muted)}.search input{border:0;outline:0;background:transparent;flex:1}.top-meta{display:flex;align-items:center;gap:12px;color:var(--muted);font-size:14px}.pill{display:inline-flex;align-items:center;gap:7px;min-height:34px;padding:0 12px;border-radius:999px;border:1px solid var(--border);background:#fff;font-weight:700}.pill:before{content:"";width:8px;height:8px;border-radius:50%;background:currentColor}.pill.ok{color:#15803d;background:#f0fdf4;border-color:#bbf7d0}.pill.err{color:#dc2626;background:#fef2f2;border-color:#fecaca}.content{max-width:1320px;margin:0 auto;padding:28px}.page-head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:22px}.page-head h1{margin:0;font-size:30px;letter-spacing:-.03em}.page-head p{margin:8px 0 0;color:var(--muted);font-size:15px}.btn{border:1px solid #cbd5e1;background:#fff;color:var(--text);min-height:40px;border-radius:11px;padding:0 14px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center}.btn-primary{background:var(--accent);border-color:var(--accent);color:#fff}.summary-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:18px}.summary-card{background:#fff;border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow);padding:18px}.summary-label{color:var(--muted);font-size:13px;font-weight:700}.summary-value{display:block;font-size:30px;line-height:1.1;font-weight:800;margin-top:6px}.board-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(340px,.65fr);gap:18px;align-items:start}.card{background:#fff;border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow);overflow:hidden}.card-head{padding:18px 20px 0;display:flex;justify-content:space-between;align-items:center}.card-head h2{margin:0;font-size:18px}.card-body{padding:16px 20px 20px}.task-list{display:grid;gap:10px}.task-row{border:1px solid var(--border);border-radius:14px;background:#fff;padding:14px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center}.task-title{font-weight:780;margin-bottom:7px}.task-desc{color:var(--muted);font-size:13px;margin:7px 0 0}.tags{display:flex;flex-wrap:wrap;gap:7px}.tag{padding:4px 9px;border-radius:8px;font-size:12px;font-weight:750;border:1px solid var(--border);background:var(--surface2);color:var(--muted)}.tag.blue{color:var(--accent);background:var(--accent-soft);border-color:#bfdbfe}.tag.red{color:#dc2626;background:#fef2f2;border-color:#fecaca}.tag.orange{color:#b45309;background:#fffbeb;border-color:#fde68a}.tag.purple{color:var(--purple);background:#f5f3ff;border-color:#ddd6fe}.task-actions{display:flex;gap:8px}.icon-btn{width:32px;height:32px;border-radius:999px;border:1px solid var(--border);cursor:pointer;font-weight:800}.icon-btn.ok{color:#15803d;background:#f0fdf4;border-color:#bbf7d0}.icon-btn.danger{color:#dc2626;background:#fef2f2;border-color:#fecaca}.timeline{display:grid;gap:12px}.timeline-item{border-left:3px solid var(--accent);background:var(--surface2);border-radius:0 13px 13px 0;padding:11px 12px}.timeline-time{font-size:12px;color:var(--muted);font-weight:750;margin-bottom:4px}.timeline-title{font-weight:750}.empty{color:var(--muted);font-size:14px;padding:18px;border:1px dashed #cbd5e1;border-radius:14px;background:var(--surface2)}.toast{position:fixed;right:24px;bottom:24px;min-width:220px;padding:12px 14px;border-radius:12px;border:1px solid var(--border);background:#fff;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.18s ease;font-weight:650}.toast.show{opacity:1;transform:translateY(0)}@media(max-width:1080px){.layout{grid-template-columns:1fr}.sidebar{position:static;height:auto}.nav{grid-template-columns:repeat(3,1fr)}.board-grid,.summary-grid{grid-template-columns:1fr}.topbar{position:static}}
</style>
</head>
<body>
<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-mark">SC</div><div><div class="brand-title">SmartCore</div><div class="brand-sub">学生智能助手</div></div></div><nav class="nav"><a class="nav-link" href="/work/board"><span class="nav-ico">⌂</span>总览</a><a class="nav-link" href="/work/add"><span class="nav-ico">＋</span>添加事件</a><a class="nav-link active" href="/work/board"><span class="nav-ico">▦</span>事项看板</a><a class="nav-link" href="/work/add"><span class="nav-ico">◇</span>灵感</a></nav></aside><section class="main"><header class="topbar"><label class="search"><span>⌕</span><input id="searchInput" placeholder="搜索事项、DDL..."></label><div class="top-meta"><span class="pill" id="apiBadge">API 待命</span><span id="lastUpdate">未刷新</span><button class="btn" id="refreshBtn">刷新</button></div></header><main class="content"><section class="page-head"><div><h1>事项看板</h1><p>独立事项看板：只加载 /api/evt，暂不触发课程、设备、日志等接口。</p></div><a class="btn btn-primary" href="/work/add">添加事件</a></section><section class="summary-grid"><article class="summary-card"><span class="summary-label">待办总数</span><strong class="summary-value" id="todoCount">0</strong></article><article class="summary-card"><span class="summary-label">已逾期</span><strong class="summary-value" id="overdueCount">0</strong></article><article class="summary-card"><span class="summary-label">未来48小时截止</span><strong class="summary-value" id="deadlineCount">0</strong></article></section><section class="board-grid"><section class="card"><div class="card-head"><h2>今日事项</h2><span class="tag blue" id="resultCount">0 条</span></div><div class="card-body"><div id="taskList" class="task-list"></div></div></section><aside class="card"><div class="card-head"><h2>未来 48 小时截止</h2></div><div class="card-body"><div id="timeline" class="timeline"></div></div></aside></section></main></section></div><div class="toast" id="toast"></div>
<script>
const state={events:[]};const $=id=>document.getElementById(id);const typeLabels={life:"生活",ddl:"DDL",course:"课程"};const prioLabels={high:"高优先级",mid:"中优先级",low:"低优先级"};function esc(v){return String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;")}function toast(t){const el=$("toast");el.textContent=t;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}function badge(k,t){const b=$("apiBadge");b.className=`pill ${k||""}`.trim();b.textContent=t}function evtTime(e){const raw=e.evtType==="ddl"?e.ddlAt:e.evtType==="course"?e.classDate:e.dueAt;if(!raw)return{date:null,label:"未设置",overdue:false};const d=new Date(raw);if(Number.isNaN(d.getTime()))return{date:null,label:raw,overdue:false};const n=new Date(),tm=new Date();tm.setDate(n.getDate()+1);const same=(a,b)=>a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();const day=same(d,n)?"今天":same(d,tm)?"明天":`${d.getMonth()+1}月${d.getDate()}日`;const time=d.toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit",hour12:false});const overdue=e.stat==="todo"&&e.evtType!=="course"&&d.getTime()<Date.now();return{date:d,label:`${day} ${time}${overdue?" · 已逾期":""}`,overdue}}function cls(e,kind){if(kind==="type"&&e==="ddl")return"purple";if(kind==="prio"&&e==="high")return"red";if(kind==="prio"&&e==="mid")return"orange";return"blue"}function render(){const q=$("searchInput").value.trim().toLowerCase();const todos=state.events.filter(e=>e.stat==="todo");const now=Date.now();const overdue=todos.filter(e=>evtTime(e).overdue);const soon=todos.filter(e=>{const t=evtTime(e);if(!t.date||e.evtType==="course")return false;const diff=t.date.getTime()-now;return diff>=0&&diff<=48*3600_000});$("todoCount").textContent=todos.length;$("overdueCount").textContent=overdue.length;$("deadlineCount").textContent=soon.length;const rows=todos.sort((a,b)=>{const ta=evtTime(a),tb=evtTime(b);if(ta.overdue!==tb.overdue)return ta.overdue?-1:1;if(!ta.date&&!tb.date)return 0;if(!ta.date)return 1;if(!tb.date)return-1;return ta.date-tb.date}).filter(e=>!q||`${e.title} ${e.desc||""} ${e.evtType} ${e.prio}`.toLowerCase().includes(q));$("resultCount").textContent=`${rows.length} 条`;$("taskList").innerHTML=rows.length?rows.map(e=>{const t=evtTime(e);return `<article class="task-row"><div><div class="task-title">${esc(e.title)}</div><div class="tags"><span class="tag ${cls(e.evtType,"type")}">${esc(typeLabels[e.evtType]||e.evtType)}</span><span class="tag ${cls(e.prio,"prio")}">${esc(prioLabels[e.prio]||e.prio)}</span><span class="tag ${t.overdue?"red":"blue"}">${esc(t.label)}</span></div>${e.desc?`<p class="task-desc">${esc(e.desc)}</p>`:""}</div><div class="task-actions"><button class="icon-btn ok" data-action="done" data-id="${esc(e.evtId)}">✓</button><button class="icon-btn danger" data-action="cancel" data-id="${esc(e.evtId)}">×</button></div></article>`}).join(""):`<div class="empty">暂无待办事项。</div>`;$("timeline").innerHTML=soon.length?soon.sort((a,b)=>evtTime(a).date-evtTime(b).date).slice(0,8).map(e=>{const t=evtTime(e);return `<div class="timeline-item"><div class="timeline-time">${esc(t.label)}</div><div class="timeline-title">${esc(e.title)}</div><div class="tags" style="margin-top:7px"><span class="tag ${cls(e.evtType,"type")}">${esc(typeLabels[e.evtType]||e.evtType)}</span><span class="tag ${cls(e.prio,"prio")}">${esc(prioLabels[e.prio]||e.prio)}</span></div></div>`}).join(""):`<div class="empty">48 小时内暂无截止事项。</div>`}async function load(){badge("","API 请求中");try{const r=await fetch("/api/evt");const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.msg||j.detail||`HTTP ${r.status}`);state.events=j.data||[];badge("ok","API 在线");$("lastUpdate").textContent="更新于 "+new Date().toLocaleTimeString("zh-CN",{hour12:false});render()}catch(e){badge("err","API 异常");toast(String(e.message||e));render()}}async function patch(id,stat){badge("","API 请求中");try{const r=await fetch(`/api/evt/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({stat})});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.msg||j.detail||`HTTP ${r.status}`);toast(stat==="done"?"已完成":"已取消");await load()}catch(e){badge("err","API 异常");toast(String(e.message||e))}}$("refreshBtn").addEventListener("click",load);$("searchInput").addEventListener("input",render);document.body.addEventListener("click",e=>{const b=e.target.closest("[data-action]");if(!b)return;if(b.dataset.action==="done")patch(b.dataset.id,"done");if(b.dataset.action==="cancel")patch(b.dataset.id,"cancelled")});render();load();
</script>
</body>
</html>"""


@router.get("/work/board", response_class=HTMLResponse)
def workBoardPage() -> str:
    return _WORK_BOARD_HTML
